package revisitledger.index;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import revisitledger.model.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class RecordIndexTest {
 @TempDir Path temp;
 static final String SHA1="a".repeat(40), SHA256="b".repeat(64);
 static RecordFacts fact(String path,long ordinal,String id,String target,String date) {
  var h=new LinkedHashMap<String,List<String>>();h.put("WARC-Record-ID",List.of(id));h.put("WARC-Target-URI",List.of(target));h.put("WARC-Date",List.of(date));h.put("X-Unknown",List.of("first","second\u0000"));
  return new RecordFacts(new RecordKey(path,ordinal),"resource","WARC/1.1",h,Optional.of(new PayloadEvidence(9,Map.of("sha1",SHA1,"sha256",SHA256),true)),List.of());
 }
 static RecordFacts fact(String path,long ordinal){return fact(path,ordinal,"<id>","https://example/","2000-01-01T00:00:00Z");}
 static <T> List<T> rows(Cursor<T> cursor)throws Exception {try(cursor){var out=new ArrayList<T>();while(cursor.next())out.add(cursor.value());return out;}}
 static void seal(RecordIndex i, String path,long records)throws IOException {i.file(new FileFacts(path,"c".repeat(64),records,true));i.seal(new ScanSummary(1,records,true));}
 @Test void roundTripStableStreamingOrderAndExactMetadata()throws Exception {try(var i=RecordIndex.create(temp,8L<<20)){assertNotNull(i);var b=fact("b.warc",1);var a2=fact("a.warc",2);var a1=fact("a.warc",1);i.record(b);i.record(a2);i.record(a1);i.file(new FileFacts("b.warc","d".repeat(64),1,true));i.file(new FileFacts("a.warc","c".repeat(64),2,true));i.seal(new ScanSummary(2,3,true));assertEquals(List.of(a1,a2,b),rows(i.records()));assertEquals(List.of(a1,a2,b),rows(i.byId("<id>")));assertEquals(Optional.of(a2),i.record(a2.key()));assertEquals(List.of(a1,a2),rows(i.recordsInFile("a.warc")));assertEquals(List.of("a.warc","b.warc"),rows(i.files()).stream().map(FileFacts::relativePath).toList());assertTrue(i.complete());}}
 @Test void exactInstantDateAndExactUri()throws Exception {try(var i=RecordIndex.create(temp,8L<<20)){assertNotNull(i);i.record(fact("a.warc",1,"<id>","https://example/%61","2000-01-01T00:00:00.100000000Z"));seal(i,"a.warc",1);assertEquals(1,rows(i.byTargetDate("https://example/%61","2000-01-01T00:00:00.1Z")).size());assertTrue(rows(i.byTargetDate("https://example/a","2000-01-01T00:00:00.1Z")).isEmpty());assertTrue(rows(i.byTargetDate("https://example/%61","2000-01-01T00:00:00.100000001Z")).isEmpty());assertTrue(rows(i.byTargetDate("https://example/%61","2000-01-01T24:00:00Z")).isEmpty());}}
 @Test void conjunctiveSelectorsTreatHeaderTextAsData()throws Exception {try(var i=RecordIndex.create(temp,8L<<20)){assertNotNull(i);i.record(fact("a.warc",1,"' OR 1=1 --","https://example/","2000-01-01T00:00:00Z"));i.record(fact("a.warc",2));seal(i,"a.warc",2);assertEquals(1,rows(i.byId("' OR 1=1 --")).size());assertTrue(rows(i.candidates(Optional.of("<id>"),Optional.of("no"),Optional.empty())).isEmpty());assertEquals(1,rows(i.candidates(Optional.of("<id>"),Optional.empty(),Optional.of("2000-01-01T00:00:00.000Z"))).size());}}
 @Test void incompleteFileInvalidatesPayloadButRetainsDiagnosticIdentity()throws Exception {try(var i=RecordIndex.create(temp,8L<<20)){assertNotNull(i);i.record(fact("a.warc",1));i.file(new FileFacts("a.warc","c".repeat(64),1,false));i.seal(new ScanSummary(1,1,false));assertFalse(i.complete());assertEquals(1,rows(i.byId("<id>" )).size());assertTrue(rows(i.concretePayloads(new DigestValue("sha1",SHA1))).isEmpty());}}
 @Test void invalidPayloadEvidenceNeverBecomesDigestCandidate()throws Exception {try(var i=RecordIndex.create(temp,8L<<20)){assertNotNull(i);var f=fact("a.warc",1);var issue=new Finding("digest_mismatch",Optional.of(f.key()),"Bad declaration",Map.of("field","WARC-Payload-Digest"));i.record(new RecordFacts(f.key(),f.type(),f.version(),f.rawHeaders(),f.payload(),List.of(issue)));i.finding(issue);seal(i,"a.warc",1);assertTrue(rows(i.concretePayloads(new DigestValue("sha1",SHA1))).isEmpty());assertEquals(List.of(issue),rows(i.findings()));}}
 @Test void validDigestCandidatesAreStableAndRepeatable()throws Exception {try(var i=RecordIndex.create(temp,8L<<20)){assertNotNull(i);var f=fact("a.warc",1);i.record(f);seal(i,"a.warc",1);assertEquals(List.of(f),rows(i.concretePayloads(new DigestValue("sha1",SHA1))));assertEquals(List.of(f),rows(i.concretePayloads(new DigestValue("sha256",SHA256))));}}
 @Test void sealIsRequiredAndSummaryCannotHideMissingFiles()throws Exception {try(var i=RecordIndex.create(temp,8L<<20)){assertNotNull(i);i.record(fact("a.warc",1));assertThrows(IOException.class,i::records);i.seal(new ScanSummary(0,1,true));assertFalse(i.complete());assertThrows(IOException.class,()->i.record(fact("a.warc",2)));}}
 @Test void fingerprintIsInsertionIndependentAndChangesWithCorpus()throws Exception {String first,second;try(var i=RecordIndex.create(temp,8L<<20)){assertNotNull(i);i.record(fact("a.warc",1));seal(i,"a.warc",1);first=i.corpusFingerprint();assertTrue(first.matches("[0-9a-f]{64}"));}try(var i=RecordIndex.create(temp,8L<<20)){assertNotNull(i);i.record(fact("a.warc",1));seal(i,"a.warc",1);second=i.corpusFingerprint();}assertEquals(first,second);try(var i=RecordIndex.create(temp,8L<<20)){assertNotNull(i);i.record(fact("a.warc",1));i.file(new FileFacts("a.warc","d".repeat(64),1,true));i.seal(new ScanSummary(1,1,true));assertNotEquals(first,i.corpusFingerprint());}}
 @Test void stateIsNamespacedSortedAndBounded()throws Exception {try(var i=RecordIndex.create(temp,8L<<20)){assertNotNull(i);i.seal(new ScanSummary(0,0,true));var s=i.state("graph");s.put("b",new byte[]{2});s.put("a",new byte[]{1});assertArrayEquals(new byte[]{1},s.get("a").orElseThrow());assertTrue(i.state("other").get("a").isEmpty());assertEquals(List.of("a","b"),rows(s.scan()).stream().map(StateEntry::key).toList());s.remove("a");assertTrue(s.get("a").isEmpty());assertThrows(IOException.class,()->s.put("huge",new byte[2<<20]));}}
 @Test void quotaFailureFailsClosedAndCleansUp()throws Exception {assertThrows(IOException.class,()->RecordIndex.create(temp,1));assertEquals(0,Files.list(temp).count());try(var i=RecordIndex.create(temp,2L<<20)){boolean failed=false;try{for(int n=1;n<10000;n++)i.record(fact("a.warc",n));}catch(IOException e){failed=true;}assertTrue(failed);assertThrows(IOException.class,()->i.seal(new ScanSummary(1,0,true)));assertFalse(i.complete());assertTrue(Files.walk(temp).filter(Files::isRegularFile).mapToLong(p->{try{return Files.size(p);}catch(IOException e){throw new UncheckedIOException(e);}}).sum()<=2L<<20);}assertEquals(0,Files.list(temp).count());}
 @Test void closingIndexClosesCursorsAndRemovesOnlyOwnedScratch()throws Exception {Files.writeString(temp.resolve("keep"),"safe");var i=RecordIndex.create(temp,8L<<20);i.record(fact("a.warc",1));seal(i,"a.warc",1);var c=i.records();assertTrue(c.next());i.close();assertThrows(IOException.class,c::next);i.close();assertEquals(List.of("keep"),Files.list(temp).map(p->p.getFileName().toString()).toList());}
}
